// src/lib/contractParts.generated.js must match the quote program in public/build (the contract CSS, the logos, CCI's and
// StormSafe's terms). It is regenerated by `npm run sync:builder`; if this fails, run: node scripts/gen-contract-parts.mjs
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { extractContractParts, PROGRAM, moduleText } from '../scripts/gen-contract-parts.mjs'
import * as parts from '../src/lib/contractParts.generated.js'

test('the contract parts are the current program\'s', () => {
  const fresh = extractContractParts(readFileSync(PROGRAM, 'utf8'))
  assert.equal(parts.CONTRACT_CSS, fresh.css)
  assert.equal(parts.SS_LOGO, fresh.ssLogo)
  assert.equal(parts.CCI_LOGO, fresh.cciLogo)
  assert.equal(parts.CCI_TERMS, fresh.cciTerms)
  assert.equal(parts.SS_TERMS, fresh.ssTerms)
})

test('the generated file is exactly what the script writes', () => {
  const fresh = extractContractParts(readFileSync(PROGRAM, 'utf8'))
  const onDisk = readFileSync(new URL('../src/lib/contractParts.generated.js', import.meta.url), 'utf8').replace(/\r\n/g, '\n')
  assert.equal(onDisk, moduleText(fresh))
})

test('the pieces the addition order needs', () => {
  assert.match(parts.CCI_TERMS, /Modification of Structure Voids Warranty/)
  assert.match(parts.CCI_TERMS, /Rev\. June 10, 2022/)
  assert.match(parts.SS_TERMS, /ALL DEPOSITS AND PAYMENTS ARE NON-REFUNDABLE/)
  assert.doesNotMatch(parts.SS_TERMS, /Carolina Carports/)
  assert.match(parts.CONTRACT_CSS, /\.c-hdr\{/)
  assert.match(parts.SS_LOGO, /^data:image\/png;base64,/)
})
